import { test, expect } from '@playwright/test';

test.describe('WebSocket Connection Tests', () => {
  let page: any;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000'); // Replace with your app's URL
  });

  test('should display initial data from WebSocket', async () => {
    const initialData = await page.locator('text=Initial Data').innerText();
    expect(initialData).toBe('Expected Initial Data'); // Replace with expected initial data
  });

  test('should update UI in real-time when new data is received', async () => {
    const updatedDataLocator = page.getByRole('status'); // Replace with appropriate role or locator
    await page.waitForTimeout(5000); // Wait for WebSocket to send updates

    const updatedData = await updatedDataLocator.innerText();
    expect(updatedData).toBe('Expected Updated Data'); // Replace with expected updated data
  });
});
